    \begin{equation} \label{eq:entropic_singleton_avg}
\log_2 K
\le
\frac{N-2(d-1)}{d-1}
\overline S_{d-1},
\qquad
\overline S_{d-1}
\coloneqq
\mathbb E_{|A|=d-1} S(A),
\end{equation}
where the average is over all regions $A$ of size $d-1$ \cite{grassl_entropic_2022}.

Moreover, for any two disjoint correctable erasure regions $A,C$ with $|A|=|C|=d-1$, defining $B=[N]\setminus(A\cup C)$,
