\section{Preliminaries}
\paragraph{Notation.}
We denote the number of qubits by $n \in \mathbb{N}$ and set
$N := 2^n$, so that each quantum register is identified with the  complex Hilbert space $\mathbb{C}^N$ of dimension $N$.  The computational basis $\zo^n$ are indexed by $[N] := \{1,\ldots,N\}$. We write $\calL(\C^N)$ for the space of linear operators on $\C^N$. For every linear operator $X \in \calL(\C^N)$, we define the Schatten $p$-norm of $X$ by  $\|X\|_p := \left( \operatorname{Tr}\left[ |X|^p \right] \right)^{1/p}$, 
for all $p \in [1,\infty]$, where $|X| := \sqrt{X^\dagger X}$. We represent $n$-qubit Hadamard transform $H^{\ot n}$ by $H$ and transpose as $\mathsf{T}$.
The parameter $t=t(n)$ denotes the number of oracle queries. For the purposes of this paper, we are primarily interested in the regime when $t$ is polynomially bounded in $n$. Throughout, sans-serif capital letters denote quantum registers. We write $\mathsf{X}_1,\ldots,\mathsf{X}_t$ for $t$ registers, each associated with a Hilbert space isomorphic to $\mathbb{C}^N$, and $\mathsf{R}$ for an arbitrarily large auxiliary register. Whenever obvious from context, we will not explicitly write registers on which an operator is supported in order to simplify presentation. We further define
\begin{equation}
[N]^t_{\dist}
:=
\left\{
(x_1,\ldots,x_t)\in [N]^t : x_i \neq x_j \text{ for all } i\neq j
\right\},
\end{equation}
to be the set of all pairwise distinct $t$-tuples. The orthogonal projector onto the corresponding distinct subspace is
\begin{equation}
\Pi^{\dist}
:=
\sum_{(x_1,\ldots,x_t)\in [N]^t_{\dist}}
|x_1,\ldots,x_t\rangle\langle x_1,\ldots,x_t|,
\end{equation}
and we denote the complementary projector by
\begin{equation}
\overline{\Pi}^{\dist}
:=
\Id_{\mathsf{X}_1,\ldots, \mathsf{X}_t}
-
\Pi^{\dist},
\end{equation}
which can be thought of `detecting a collision' on the full $t$-copy Hilbert space. An `equality projector' detects a collision on a given bipartition.
\begin{equation}
{\Pi}^{\eq}_{\X_i, \X_j} = \sum_{x\in [N]} \ketbra{x}{x}_{\X_i} \otimes \ketbra{x}{x}_{\X_j},
\end{equation}
and acts as identity on the remaining registers. $\overline{\Pi}^{\dist}$ and ${\Pi}^{\eq}_{\X_i, \X_j}$ are related by an operator inequality (\Cref{fact:dist-eq-op-ineq})

We write $\mu_{\Haar}$ for the normalized Haar measure on the relevant compact group. Depending on context, this denotes the normalized Haar measure on $\mathrm{U}(N)$ or on $\mathrm{O}(N)$.
We denote by $\Cl_{\C}(N)$  (resp. $\Cl_{\R}(N)$) the complex (resp. real) Clifford group of dimension $N$. 
Given a finite set $\calE$, we write $x \leftarrow \calE$ to mean that $x$ is sampled uniformly from $\calE$. More generally, if $\mu$ is a probability measure on a measurable space $X$, then $x \leftarrow \mu$ means that $x$ is sampled according to $\mu$.
The following two operators 
\begin{equation}
|\Omega\rangle := \sum_{x\in [N]} |x,x\rangle \qquad \SWAP
=
\sum_{x,y\in[N]}
\ket{x,y}\bra{y,x}
\end{equation}
on $\calH^{\ot 2}$ shall appear multiple 
times in this work.
The unnormalized maximally entangled state 
on two $N$-dimensional registers is denoted as $\ket{\Omega}$ and normalized maximally entangled state vector  $\ket{\Omega}/\sqrt{N}$ is denoted by $\ket{\Phi}$.

Let $\Sym_N$ be the symmetric group on $N$ elements. Then for $\pi \in \Sym_N$,
\begin{equation}
P_{\pi} := \sum_{x \in [N]} \ketbra{\pi(x)}{x}.
\end{equation}
We will omit the dependence on $\pi$ and write $P$ to simplify notation. Unless otherwise specified, $P$ corresponds to $P_{\pi}$, where $\pi \leftarrow \Sym_N$. For a diagonal phase operator in the computational basis, we write
\begin{equation}
F_j=\sum_{x\in[N]}\omega_q^{\,f_j(x)}\ketbra{x}{x},\qquad f_j:[N]\to \{0,1,\ldots, K-1\},
\end{equation}
where $\omega_q\coloneqq e^{2\pi i/q}$ is the $q$-th root of unity for some $q\geq2$ and $f_j$ is sampled uniformly randomly from the set of all functions $[N] \to \{0,1,\ldots, K-1\}$, where $K \leq N$. To avoid clutter, we will simply write $F$, which is to be understood as a diagonal phase operator with complex phases. Whenever needed, we will make the parameters $q$ and $K$ explicit.

We write $\negl(n)$ for negligible functions. That is any function that is $o(1/n^c)$ for all $c>0$.
Unless stated otherwise, we only consider PRUs against adversaries that have \emph{forward-only} oracle access and
can query the oracle \emph{only in parallel} (non-adaptively). Our goal is to understand the necessary resources
for constructing PRUs, so we work with this weakest form of security. Any lower bound or impossibility result
proved in this regime applies \emph{a fortiori} to stronger notions of PRU security (for example, allowing
adaptive queries or inverse-oracle access).
\begin{definition}[Parallel (forward) pseudorandom unitaries]\label{def:parallel-pru}
We say $\{\mathcal{U}_n\}_{n\in\mathbb{N}}$ is a secure \emph{parallel forward PRU} if, for all $n\in\mathbb{N}$,
\begin{equation}
\mathcal{U}_n=\{U_k\}_{k\in\mathcal{K}_n}
\end{equation}
is a set of $n$-qubit unitaries (where $\mathcal{K}_n$ denotes the keyspace) satisfying the following properties:
\begin{itemize}
  \item \textbf{Efficient computation:} There exists a $\poly(n)$-time quantum algorithm that implements the
  $n$-qubit unitary $U_k$ on input $k\in\mathcal{K}_n$.

  \item \textbf{Parallel forward-query indistinguishability from Haar:}
  For any QPT algorithm $\calA$, whose oracle access is \emph{forward-only} and \emph{non-adaptive}, and that measures a two-outcome observable $D_{\X\mathsf{R}}$
  with eigenvalues $\{0,1\}$ after the queries, we have
  \begin{equation}
  \left|
  \mathbb{E}_{\mathcal{O}\leftarrow \mathcal{U}_n}\,
  \tr\left(D_{\X,\mathsf{R}} \cdot \left|\calA^{\mathcal{O}}\right\rangle\left\langle \calA^{\mathcal{O}}\right|_{\X\mathsf{R}}\right)
  -
  \mathbb{E}_{\mathcal{O}\leftarrow \mu_{\Haar}}\,
  \tr\left(D_{\X,\mathsf{R}} \cdot \left|\calA^{\mathcal{O}}\right\rangle\left\langle \calA^{\mathcal{O}}\right|_{\X,\mathsf{R}}\right)
  \right|
  \le \negl(n),
  \end{equation}
  where
 $\left|\calA^{\mathcal{O}}\right\rangle \coloneqq \calA_{1, \X,\mathsf{R}} \big(\mathcal{O}^{\otimes q(n)}_{\X} \otimes \Id_{\mathsf{R}} \big) \calA_{0, \X,\mathsf{R}}\ket{\psi_0}_{\X,\mathsf{R}}$, for any $q(n)=\poly(n)$, where $\mathsf{X}$ is a $q(n)$ qubit query register, $\mathsf{R}$ is an arbitrarily large reference register, $\calA_{0, \X,\mathsf{R}}\ket{\psi_0}, \calA_{1, \X,\mathsf{R}}$ are arbitrary unitaries on the joint register $\X,\mathsf{R}$, and $\ket{\psi_0}_{\X,\mathsf{R}}$ is some efficiently preparable quantum state vector.
\end{itemize}
\end{definition}
We will also consider ensembles that form PRUs on a set of input states $\cal S$, meaning that the QPT distinguisher is only allowed to query the unknown unitary on states in $\cal S$.
Whenever we say $\cal E$ is a PRU ensemble we mean a PRU in the sense of \Cref{def:parallel-pru}, unless otherwise specified.

\paragraph{Representation theory background.}
Let $\operatorname{GL}(N)$ be the group of invertible complex $N\times N$ matrices, equivalently the group of invertible linear maps on $\calH$. We will use the following notions.
\begin{definition}[Representation]
Let $G$ be a group. A representation of $G$ 
on $\calH$ is a group homomorphism
$R:G\to \operatorname{GL}(N)$. Given such a representation $R$, the associated $t$-fold tensor representation acts on $\calH^{\otimes t}$ by
\begin{equation}
g \mapsto R(g)^{\otimes t},
\qquad g\in G.
\end{equation}
If $R$ is a representation, then $g\mapsto R(g)^{\otimes t}$ is also a representation of $G$.
\end{definition}

\begin{definition}[$t$-th order commutant]\label{def:t-th-order-commutant}
Let $R$ be a representation of a group $G$ on $\calH$. The $t$-th order commutant of $G$ with respect to $R$, denoted $\Comm(G, t)$, is the subspace of $\calL\left((\C^N)^{\otimes t}\right)$ given by
\begin{equation}
\Comm(G, t)
=
\bigl\{
A\in \calL\left((\C^N)^{\otimes t}\right)
\big|
[A,R(g)^{\otimes t}]=0 \text{ for all } g\in G
\bigr\}.
\end{equation}
\end{definition}

We will primarily work with the unitary and the orthogonal groups of dimension $N$, which we denote as $\rmU(N)$ and $\rmO(N)$, respectively. 
We interchangably use the terms $t$-wise twirl and $t$-th moment operator.
\begin{definition}[$t$-wise twirl]
Let $\calE$ be an ensemble of unitary operators. The associated $t$-fold twirling channel, also called the $t$-th moment operator, is the linear map
\begin{equation}
\mathcal{M}_{\calE}^{(t)}(X)
:=
\mathbb{E}_{U \leftarrow \calE}\left[
U^{\otimes t} X U^{\dagger,\otimes t}
\right],
\qquad
X \in \mathcal{L}\bigl((\mathbb{C}^N)^{\otimes t}\bigr).
\end{equation}
If $U$ is distributed according to Haar measure on $\mathrm{U}(d)$, we write
\begin{equation}
\mathcal{M}_{U_{\Haar}}^{(t)}(X)
:=
\mathbb{E}_{U \leftarrow \mu_{\Haar}}\left[
U^{\otimes t} X U^{\dagger,\otimes t}
\right].
\end{equation}
\end{definition}
The twirling channel w.r.t.\ the orthgonal group is similarly defined and denoted as $\mathcal{M}_{O_{\Haar}}^{(t)}(X)$.

\begin{definition}[Haar measure]
Let $\rmU(2^n)$ be the group of $n$-qubit unitaries. The Haar measure on $U(2^n)$ is the unique probability measure $\mu_{\mathrm{Haar}}$ on $U(2^n)$ that is invariant under both left and right multiplication, namely
\begin{equation}
\mu_{\mathrm{Haar}}(VS)=\mu_{\mathrm{Haar}}(S)
\quad\text{and}\quad
\mu_{\mathrm{Haar}}(SV)=\mu_{\mathrm{Haar}}(S)
\end{equation}
for every measurable set $S \subseteq U(2^n)$ and every $V \in U(2^n)$.
\end{definition}

For brevity, we will sometimes use $U_{\Haar}$ and $O_{\Haar}$ to denote a Haar random unitary or orthgonal matrix.

\begin{definition}[Unitary $t$-design]
A distribution $\mathcal{D}$ over $n$-qubit unitaries is called a \emph{unitary $t$-design} if
\begin{equation}
    \E_{U \leftarrow \mathcal{D}}\left[ U^{\otimes t}\otimes U^{\dagger,\otimes t}\right]
    =
    \int_{U(2^n)} U^{\otimes t}\otimes U^{\dagger,\otimes t}\, d\mu(U),
\end{equation}
where $\mu$ denotes the Haar measure on $U(2^n)$.
\end{definition}

Since we mostly address necessary conditions for PRUs, the natural choice is the standard notion of an additive error or diamond norm error $t$-design.

\begin{definition}[Additive error unitary $t$-design]
    For $\varepsilon > 0$, an ensemble $\calE$ is an $\varepsilon$-approximate additive error unitary $t$-design if 
    \begin{equation}
\bigl\|
\mathcal{M}_{\calE}^{(t)}-\mathcal{M}_{U_{\Haar}}^{(t)}
\bigr\|_\diamond
\leq
\varepsilon,   
\end{equation}
where $\bigl\|
\mathcal{M}_{\calE}^{(t)}-\mathcal{M}_{\calE'}^{(t)}
\bigr\|_\diamond \coloneqq \max_{\rho}\bigl\| \mathcal{M}_{\calE}^{(t)}(\rho)-\mathcal{M}_{\calE'}^{(t)}(\rho) \bigr\|_1$. The maximization is over all states on $nt$ system qubits with arbitrarily large auxiliary registers.
\end{definition}

An ensemble is called a {\em state} $t$-design if the input states are restricted to be of the form $\rho = \ketbra{\psi}{\psi}^{\ot t}$ for any (normalized) $\ket{\psi} \in (\C^2)^{\ot n}$ \cite{mele_introduction_2024,haah_efficient_2024}. Additive error orthogonal designs 
are similarly defined but w.r.t.\ the 
orthogonal group $\rmO(N)$.

\paragraph{Useful facts.}
Here we recall some well-known facts that we will refer to later.

\begin{fact}[Dirichlet kernel identity]\label{fact:Dirichlet-kernel-identity}
$\sum_{k=0}^{N-1} e^{ikx}
=
e^{i(N-1)x/2}\,\frac{\sin(Nx/2)}{\sin(x/2)}$.
\end{fact}

\begin{fact}[Collision-projector inequalities]\label{fact:dist-eq-op-ineq}
${\Pi}^{\mathsf{eq}}_{\X_i, \X_j} \preceq \overline{\Pi}^{\dist} \preceq \sum_{1\leq i<j\leq t} {\Pi}^{\mathsf{eq}}_{\X_i, \X_j}$
\end{fact}
\begin{proof}
  Since $\overline{\Pi}^{\dist}$ and $\Pi^{\eq}_{\X_i,\X_j}$ are diagonal in the computational basis $(x_1,\ldots,x_t)\in [N]^t$, it suffices to compare diagonal matrix elements on each basis vector, which reduces to the scalar inequality
\begin{equation}
\mathbf{1}[x_i=x_j] \leq  \mathbf{1}\left[(x_1,\ldots,x_t)\notin [N]^t_{\mathrm{dist}}\right]
\leq
\sum_{1\leq i<j\leq t}\mathbf{1}[x_i=x_j].
\end{equation}
The first inequality holds because if $x_i=x_j$, then the tuple is not pairwise distinct. The second inequality holds because a non-distinct tuple contains at least one colliding pair.
\end{proof}

\begin{fact}[Character orthogonality]\label{fact:character-ortho}
For $x, w\in\mathbb{F}_2^n$, define the character $\chi_w:\mathbb{F}_2^n\to\{\pm1\}$
\begin{equation}
\chi_w(x):=(-1)^{\langle x,w\rangle}, \qquad
\langle x,w\rangle := \sum_{i=1}^n x_i w_i \pmod 2.
\end{equation}
Then we have that
$
\mathbb{E}_{x\in\mathbb{F}_2^n}\big[\chi_w(x)\chi_{w'}(x)\big]=\delta_{w,w'}.
$
Equivalently,
$
\sum_{x\in\mathbb{F}_2^n}\chi_w(x)\chi_{w'}(x)
=
N\delta_{w,w'}.
$
\end{fact}

